    /// The form whose discriminant (`op as u16`) is `value`.
    #[inline]
    pub const fn from_u16(value: u16) -> Option<Self> {
        if (value as usize) < Self::ALL.len() {
            Some(Self::ALL[value as usize])
        } else {
            None
        }
    }

